import shlex
import shutil
import subprocess

from pydantic import BaseModel, Field
from agenthub.sdk import (project_root, tool, ToolContext, ToolError, ToolResponse,
                          ToolConfigResponse, ToolInitResponse, tool_config, tool_init)

ALLOWED = {"npm", "npx", "node", "tsc", "eslint", "git", "find", "curl"}


class Args(BaseModel):
    command: str = Field(description="Command to run, e.g. `npx tsc --noEmit`. Shell operators are not allowed.")
    cwd: str = Field(".", description="Directory relative to the project root, e.g. solid-ui or solid-api.")


@tool_config
def config() -> ToolConfigResponse:
    return ToolConfigResponse(required_secrets=[])


@tool_init
def init() -> ToolInitResponse:
    root = project_root()
    if not root.is_dir():
        return ToolInitResponse(success=False, message=f"Project root {root} does not exist.")
    missing = sorted(command for command in ALLOWED if shutil.which(command) is None)
    if "npx" in missing:
        return ToolInitResponse(success=False, message="npx is not on PATH; install Node.js.")
    return ToolInitResponse(success=True, message=f"Project root {root} is ready." +
                            (f" Not on PATH: {', '.join(missing)}." if missing else ""))


@tool(name="bash", description="Run an allowlisted command (npm, npx, node, tsc, eslint, git, find, curl) in the "
                               "consuming SolidX project.")
def bash(args: Args, ctx: ToolContext) -> ToolResponse:
    if any(operator in args.command for operator in (";", "&&", "||", "|", ">", "<", "`", "$(", "\n")):
        raise ToolError("invalid_command", "Shell operators and substitution are forbidden",
                        guidance="Run one command per call; use `cwd` instead of `cd`.")
    parts = shlex.split(args.command)
    if not parts or parts[0] not in ALLOWED:
        raise ToolError("invalid_command", f"Only {', '.join(sorted(ALLOWED))} are available")
    if parts[0] == "find" and any(part in {"-exec", "-execdir", "-ok", "-okdir", "-delete"}
                                   or part.startswith("-fprint") for part in parts[1:]):
        raise ToolError("invalid_command", "Unsafe find option")
    if parts[0] == "git" and any(part in {"-c", "--config-env", "--exec-path", "config"} or
                                 part.startswith(("-c=", "--config-env=", "--exec-path="))
                                 for part in parts[1:]):
        raise ToolError("invalid_command", "Unsafe git option")
    root = project_root()
    cwd = (root / args.cwd).resolve()
    if not cwd.is_relative_to(root):
        raise ToolError("path_outside_workspace", f"cwd '{args.cwd}' is outside the project root")
    if not cwd.is_dir():
        raise ToolError("path_not_found", f"cwd '{args.cwd}' does not exist")
    try:
        completed = subprocess.run(parts, cwd=cwd, capture_output=True, text=True, errors="replace", timeout=600,
                                   check=False)
    except subprocess.TimeoutExpired as exc:
        raise ToolError("command_timeout", "Command exceeded 600 seconds", guidance="Run a narrower command.") from exc
    # Build and test failures are reported at the end of the output, so keep the tail.
    return ToolResponse({"status": completed.returncode, "cwd": str(cwd.relative_to(root)) or ".",
                         "stdout": completed.stdout[-50000:], "stderr": completed.stderr[-10000:],
                         "truncated": len(completed.stdout) > 50000 or len(completed.stderr) > 10000})

"""Consuming-project search/read/edit/write, ported from the SolidX agent's ``filesystem_tool``.

Paths resolve against the consuming project root (``CONTAINER_SOLIDX_CONSUMING_PROJECT_ROOT``, then
``SOLIDX_PROJECT_ROOT``, then the working directory) or the Agent Hub tool staging area. Edits use MCP-style
{oldText, newText} pairs: exact substring first, then a whitespace-tolerant line match; otherwise the call
fails so the model re-reads instead of anchoring to the wrong place. Search uses ripgrep, falling back to grep.
"""

import json
import os
import re
import shutil
import subprocess
from pathlib import Path
from secrets import token_hex
from typing import Literal

from pydantic import BaseModel, Field, field_validator
from agenthub.sdk import (project_root, tool, ToolContext, ToolError, ToolResponse,
                          ToolConfigResponse, ToolInitResponse, tool_config, tool_init)

DEFAULT_FRONTEND_ROOT = "solid-ui"


class Edit(BaseModel):
    oldText: str
    newText: str


class Args(BaseModel):
    action: Literal["search", "read", "edit", "write"] = Field(description="One of search, read, edit, write.")
    query: str | None = Field(None, description="Required for action=search. Regex/text query for search.")
    path: str | None = Field(None, description="For search/read/edit/write. For search defaults to solid-ui when "
                                               "omitted.")
    glob: str | None = Field(None, description='Optional glob filter for action=search (for example "*.tsx").')
    case_sensitive: bool = Field(False, description="For action=search. Whether match is case-sensitive.")
    max_matches: int = Field(200, description="For action=search. Maximum total matches returned.")
    context_lines: int = Field(2, description="For action=search. Number of context lines around each match.")
    start_line: int | None = Field(None, description="For action=read. Optional 1-based start line.")
    end_line: int | None = Field(None, description="For action=read. Optional 1-based end line (inclusive).")
    max_chars: int = Field(20000, description="For action=read. Maximum returned character count.")
    edits: list[Edit] | None = Field(None, description=(
        "Required for action=edit. Non-empty list of {oldText, newText} pairs. Each oldText must appear in the file "
        "(exact substring or whitespace-tolerant line match). On no match the call fails with edit_no_match; re-read "
        "the file and resubmit instead of retrying the same edit. New file creation belongs to action=write."))
    content: str | None = Field(None, description="Required for action=write. Full UTF-8 text content for the "
                                                  "target file.")
    overwrite: bool = Field(False, description="For action=write. When false (default) writing fails with "
                                               "file_exists if the target already exists.")
    dry_run: bool = Field(False, description="For action=edit. Validate edits without persisting changes.")

    @field_validator("edits", mode="before")
    @classmethod
    def parse_edits(cls, value):
        # Models sometimes send complex arguments as a JSON-encoded string.
        if isinstance(value, str):
            try:
                return json.loads(value) if value.strip() else value
            except json.JSONDecodeError as exc:
                raise ValueError("edits must be an array of {oldText, newText} objects, not a quoted string") from exc
        return value


def _resolve(path: str) -> Path:
    root = project_root()
    raw = Path(path.strip())
    resolved = raw.resolve() if raw.is_absolute() else (root / raw).resolve()
    staging = (Path.home() / ".solidx" / "agent-hub" / "tools").resolve()
    if not any(resolved.is_relative_to(allowed) for allowed in (root, staging)):
        raise ToolError("path_outside_workspace", f"Path '{path}' is outside workspace root '{root}' and the "
                        f"Agent Hub tool staging area '{staging}'", retryable=True,
                        guidance="Provide a path under the workspace root or Agent Hub tool staging area.")
    return resolved


def _relative(path: Path) -> str:
    root = project_root()
    return str(path.relative_to(root)) if path.is_relative_to(root) else str(path)


def _read_text(target: Path, relative: str) -> str:
    try:
        return target.read_text(encoding="utf-8")
    except UnicodeDecodeError as exc:
        raise ToolError("binary_or_non_utf8", f"File '{relative}' is not UTF-8 text",
                        guidance="Use this tool only for UTF-8 text files.") from exc


def _atomic_write(target: Path, content: str) -> None:
    temporary = target.parent / f"{target.name}.{token_hex(16)}.tmp"
    try:
        temporary.write_text(content, encoding="utf-8")
        os.replace(temporary, target)
    finally:
        temporary.unlink(missing_ok=True)


def _indent(line: str) -> str:
    return line[:len(line) - len(line.lstrip(" \t"))]


def _apply_edit(content: str, old_text: str, new_text: str) -> str | None:
    old_text, new_text = old_text.replace("\r\n", "\n"), new_text.replace("\r\n", "\n")
    if old_text in content:
        return content.replace(old_text, new_text, 1)
    old_lines, lines = old_text.split("\n"), content.split("\n")
    for i in range(len(lines) - len(old_lines) + 1):
        if not all(old.strip() == line.strip() for old, line in zip(old_lines, lines[i:i + len(old_lines)])):
            continue
        base = _indent(lines[i])
        rebuilt = []
        for j, line in enumerate(new_text.split("\n")):
            old_indent, new_indent = (_indent(old_lines[j]) if j < len(old_lines) else ""), _indent(line)
            if j == 0:
                rebuilt.append(base + line.lstrip())
            elif old_indent and new_indent:
                rebuilt.append(base + " " * max(0, len(new_indent) - len(old_indent)) + line.lstrip())
            else:
                rebuilt.append(line)
        lines[i:i + len(old_lines)] = rebuilt
        return "\n".join(lines)
    return None


def _search_command(backend: str, query: str, root: Path, args: Args) -> list[str]:
    if backend == "rg":
        command = ["rg", "--json", "--line-number", "--column", "--context", str(args.context_lines)]
        command += [] if args.case_sensitive else ["-i"]
        command += ["-g", args.glob] if args.glob else []
    else:
        command = ["grep", "-n", "-E", "--binary-files=without-match", "--color=never", "-C", str(args.context_lines)]
        command += ["-R"] if root.is_dir() else []
        command += [] if args.case_sensitive else ["-i"]
        command += [f"--include={args.glob}"] if args.glob else []
    return command + [query, str(root)]


def _repair_regex(query: str) -> str:
    """Escape a regex the model meant literally; keep top-level alternation."""
    parts = [part for part in query.split("|") if part]
    return "|".join(re.escape(part) for part in parts) if len(parts) > 1 else re.escape(query)


def _match(path: str, line: int, column: int, text: str, context: dict, context_lines: int) -> dict:
    def around(numbers):
        return [{"line": number, "text": context[(path, number)]} for number in numbers if (path, number) in context]
    return {"path": _relative(Path(path).resolve()), "line": line, "column": column, "preview": text,
            "before": around(range(max(1, line - context_lines), line)),
            "after": around(range(line + 1, line + context_lines + 1))}


def _parse_rg(stdout: str, args: Args) -> list[dict]:
    events = []
    for line in stdout.splitlines():
        try:
            events.append(json.loads(line))
        except json.JSONDecodeError:
            continue
    context = {(event["data"]["path"]["text"], event["data"]["line_number"]):
               event["data"]["lines"].get("text", "").rstrip("\n") for event in events if event.get("type") == "context"}
    matches = []
    for event in events:
        if event.get("type") != "match":
            continue
        data = event["data"]
        submatches = data.get("submatches") or [{"start": 0}]
        matches.append(_match(data["path"]["text"], data["line_number"], submatches[0]["start"] + 1,
                              data["lines"].get("text", "").rstrip("\n"), context, args.context_lines))
        if len(matches) >= args.max_matches:
            break
    return matches


def _parse_grep(stdout: str, args: Args) -> list[dict]:
    pattern = re.compile(r"^(.*?)([:\-])(\d+)([:\-])(.*)$")
    rows = [match.groups() for raw in stdout.splitlines() if raw.strip() not in {"", "--"}
            and (match := pattern.match(raw))]
    context = {(path, int(line)): text for path, first, line, second, text in rows if (first, second) != (":", ":")}
    matches = []
    for path, first, line, second, text in rows:
        if (first, second) == (":", ":"):
            matches.append(_match(path, int(line), 1, text, context, args.context_lines))
            if len(matches) >= args.max_matches:
                break
    return matches


def _search(args: Args) -> ToolResponse:
    if not (args.query or "").strip():
        raise ToolError("missing_query", "query is required for action='search'")
    if args.max_matches <= 0:
        raise ToolError("invalid_max_matches", "max_matches must be greater than 0")
    if args.context_lines < 0:
        raise ToolError("invalid_context_lines", "context_lines cannot be negative")
    root = _resolve(args.path or DEFAULT_FRONTEND_ROOT)
    if not root.exists():
        raise ToolError("path_not_found", f"Search path does not exist: '{_relative(root)}'. Drop the `path` (or pass "
                        "a parent that exists) and use a `glob` filter to scope the search instead.", retryable=True,
                        guidance="Search from a directory that exists and narrow with `glob`, e.g. "
                                 "glob='**/CurrencyExchange/*.tsx'.")
    backend = "rg" if shutil.which("rg") else "grep" if shutil.which("grep") else None
    if backend is None:
        raise ToolError("search_backend_not_found", "Neither ripgrep (rg) nor grep is available in PATH",
                        guidance="Install ripgrep (recommended) or grep and retry.")
    query = args.query

    def run(text):
        return subprocess.run(_search_command(backend, text, root, args), capture_output=True, text=True,
                              encoding="utf-8", errors="replace", timeout=120, check=False)

    completed = run(query)
    if completed.returncode not in (0, 1) and "regex parse error" in completed.stderr.lower() \
            and _repair_regex(query) != query:
        query = _repair_regex(query)
        completed = run(query)
    if completed.returncode not in (0, 1):
        stderr = completed.stderr.strip() or "search command failed."
        if "No such file or directory" in stderr or "os error 2" in stderr:
            raise ToolError("path_not_found", stderr[:2000], retryable=True,
                            guidance="Search from a directory that exists and narrow with `glob`.")
        raise ToolError("search_failed", stderr[:2000])
    matches = (_parse_rg if backend == "rg" else _parse_grep)(completed.stdout, args)
    return ToolResponse({"query": query, "path": _relative(root), "backend": backend, "glob": args.glob,
                         "case_sensitive": args.case_sensitive, "context_lines": args.context_lines,
                         "count": len(matches), "truncated": len(matches) >= args.max_matches, "matches": matches})


def _read(args: Args, target: Path, relative: str) -> ToolResponse:
    if args.max_chars <= 0:
        raise ToolError("invalid_max_chars", "max_chars must be greater than 0")
    if args.start_line is not None and args.start_line <= 0:
        raise ToolError("invalid_start_line", "start_line must be greater than 0 when provided")
    if args.end_line is not None and args.end_line <= 0:
        raise ToolError("invalid_end_line", "end_line must be greater than 0 when provided")
    if args.start_line and args.end_line and args.start_line > args.end_line:
        raise ToolError("invalid_line_range", "start_line cannot be greater than end_line")
    lines = _read_text(target, relative).splitlines(keepends=True)
    selected = "".join(lines[(args.start_line or 1) - 1:args.end_line or len(lines)])
    return ToolResponse({"path": relative, "start_line": args.start_line, "end_line": args.end_line,
                         "total_lines": len(lines), "size_bytes": target.stat().st_size,
                         "truncated": len(selected) > args.max_chars, "content": selected[:args.max_chars]})


def _edit(args: Args, target: Path, relative: str) -> ToolResponse:
    if not args.edits:
        raise ToolError("invalid_edits", "edits must be a non-empty list of {oldText, newText} pairs")
    for index, item in enumerate(args.edits):
        if item.oldText == item.newText:
            raise ToolError("noop_edit", f"edits[{index}] has identical oldText and newText (no-op)")
    original = _read_text(target, relative).replace("\r\n", "\n")
    modified = original
    for index, item in enumerate(args.edits):
        result = _apply_edit(modified, item.oldText, item.newText)
        if result is None:
            raise ToolError("edit_no_match", f"edits[{index}].oldText not found in '{relative}'. Re-read the file to "
                            "capture the current content, then resubmit.", retryable=True,
                            guidance="Call action='read' on this path to get the current content, then build a new "
                                     "oldText that matches verbatim (or differs only in whitespace per line).")
        modified = result
    changed = not args.dry_run and modified != original
    if changed:
        _atomic_write(target, modified)
    return ToolResponse({"dry_run": args.dry_run, "workspace_root": str(project_root()),
                         "allowed_scope": "workspace/**", "path": relative, "edit_count": len(args.edits),
                         "files_changed": [relative] if changed else [],
                         "files_validated": [relative] if args.dry_run else []})


def _write(args: Args, target: Path, relative: str) -> ToolResponse:
    if args.content is None:
        raise ToolError("missing_content", "content is required for action='write'")
    if target.is_dir():
        raise ToolError("not_a_file", f"Path is not a file: '{relative}'")
    existed = target.exists()
    if existed and not args.overwrite:
        raise ToolError("file_exists", f"File already exists: '{relative}'. Pass overwrite=true to replace it.",
                        retryable=True, guidance="Use action='edit' for targeted changes, or pass overwrite=true.")
    target.parent.mkdir(parents=True, exist_ok=True)
    _atomic_write(target, args.content)
    return ToolResponse({"path": relative, "created": not existed, "overwritten": existed,
                         "size_bytes": target.stat().st_size})


@tool_config
def config() -> ToolConfigResponse:
    return ToolConfigResponse(required_secrets=[])


@tool_init
def init() -> ToolInitResponse:
    root = project_root()
    if not root.is_dir():
        return ToolInitResponse(success=False, message=f"Project root {root} does not exist.")
    backend = "ripgrep" if shutil.which("rg") else "grep" if shutil.which("grep") else None
    if backend is None:
        return ToolInitResponse(success=False, message="Neither ripgrep (rg) nor grep is on PATH.")
    return ToolInitResponse(success=True, message=f"Project root {root} is ready; search uses {backend}.")


@tool(name="filesystem", description="Search, read, edit, or write files in the consuming SolidX project.")
def filesystem(args: Args, ctx: ToolContext) -> ToolResponse:
    if args.action == "search":
        return _search(args)
    if not (args.path or "").strip():
        raise ToolError("missing_path", f"path is required for action='{args.action}'")
    target = _resolve(args.path)
    relative = _relative(target)
    if args.action == "write":
        return _write(args, target, relative)
    if not target.exists():
        raise ToolError("file_not_found", f"File not found: '{relative}'." +
                        (" Use action='write' to create it." if args.action == "edit" else ""), retryable=True)
    if not target.is_file():
        raise ToolError("not_a_file", f"Path is not a file: '{relative}'")
    return _read(args, target, relative) if args.action == "read" else _edit(args, target, relative)

