"""Read-only SQL against a consuming project database on Microsoft SQL Server (pymssql driver).

SQL Server has no read-only transaction mode and T-SQL allows several statements without ``;``, so safety
comes from three layers: the statement check below (applied after string literals and quoted identifiers are
removed), a transaction that is always rolled back, and, for a hard guarantee, a read-only login supplied in
``AGENTHUB_READONLY_DATABASE_URL`` (for example a ``db_datareader`` user).
"""

import os
import re
from functools import lru_cache

from pydantic import BaseModel, Field
from sqlalchemy import create_engine, text
from sqlalchemy.engine import make_url
from agenthub.sdk import (tool, ToolContext, ToolError, ToolResponse, ToolConfigResponse,
                          ToolInitResponse, tool_config, tool_init)

BACKEND = "mssql"
_FORBIDDEN_SQL_RE = re.compile(
    r"\b(insert|update|delete|merge|drop|truncate|alter|create|grant|revoke|deny|exec|execute|into|"
    r"openrowset|opendatasource|openquery|openxml|bulk|backup|restore|dbcc|shutdown|kill|waitfor|use|set|"
    r"declare|begin|commit|rollback|save|reconfigure|checkpoint|go)\b|\b(?:sp|xp)_\w+",
    re.IGNORECASE,
)
_ALLOWED_START_RE = re.compile(r"^\s*(select|with)\b", re.IGNORECASE)
_SQL_COMMENT_RE = re.compile(r"(--[^\n]*|/\*.*?\*/)", re.DOTALL)
# String literals ('it''s', N'...') and quoted identifiers ([order], "update") cannot hide statements.
_QUOTED_RE = re.compile(r"N?'(?:[^']|'')*'|\[(?:[^\]]|\]\])*\]|\"(?:[^\"]|\"\")*\"", re.IGNORECASE)


class Args(BaseModel):
    query: str = Field(description="T-SQL SELECT or WITH statement to execute. Use TOP, not LIMIT.")
    datasource: str = Field("default", description='Datasource name (currently informational; default "default").')
    limit: int = Field(100, description="Maximum rows to return (default 100, max 1000).")


def _database_url():
    raw = os.environ.get("AGENTHUB_READONLY_DATABASE_URL") or os.environ.get("DATABASE_URL")
    if not raw:
        raise ToolError("db_query_error", "No project database is configured.")
    url = make_url(raw)
    if url.get_backend_name() != BACKEND:
        raise ToolError("unsupported_database", f"The project database is {url.get_backend_name()}, not SQL Server.",
                        guidance="Use run_read_only_postgres for PostgreSQL.")
    return url.set(drivername="mssql+pymssql")


@lru_cache(maxsize=2)
def _engine(url):
    # timeout: per-query seconds; login_timeout: connect seconds.
    return create_engine(url, pool_pre_ping=True, pool_size=2, max_overflow=0,
                         connect_args={"timeout": 30, "login_timeout": 10})


def _validate(sql: str) -> str:
    cleaned = _SQL_COMMENT_RE.sub("", sql or "").strip()
    if cleaned.endswith(";"):
        cleaned = cleaned[:-1].rstrip()
    if not cleaned:
        raise ToolError("invalid_query", "Query is empty.")
    code = _QUOTED_RE.sub("''", cleaned)
    if ";" in code:
        raise ToolError("multiple_statements_not_allowed", "Only one read-only SQL statement is allowed.")
    if not _ALLOWED_START_RE.match(code):
        raise ToolError("query_must_be_read_only", "Only read-only queries are allowed (SELECT/WITH).",
                        retryable=True, guidance="Provide a read-only query. For DELETE/UPDATE/INSERT requests, "
                                                 "ask for SQL generation only.")
    if match := _FORBIDDEN_SQL_RE.search(code):
        raise ToolError("forbidden_sql_operation", f"'{match.group(0)}' is not allowed in this tool.",
                        retryable=True, guidance="Use a single SELECT/WITH query. SELECT ... INTO, EXEC, and "
                                                 "procedures are not allowed.")
    return cleaned


def _plain(value):
    return value if value is None or isinstance(value, (str, int, float, bool)) else str(value)


@tool_config
def config() -> ToolConfigResponse:
    # DATABASE_URL is the runtime's project database, not a Core secret.
    return ToolConfigResponse(required_secrets=[])


@tool_init
def init() -> ToolInitResponse:
    try:
        url = _database_url()
    except ToolError as exc:
        return ToolInitResponse(success=False, message=str(exc))
    engine = create_engine(url, connect_args={"timeout": 5, "login_timeout": 5})
    try:
        with engine.connect() as connection:
            connection.execute(text("SELECT 1"))
    except Exception as exc:
        return ToolInitResponse(success=False, message=f"Could not query the project database ({type(exc).__name__}).")
    finally:
        engine.dispose()
    return ToolInitResponse(success=True, message="SQL Server project database connection confirmed.")


@tool(name="run_read_only_mssql",
      description="Execute a single read-only T-SQL SELECT/WITH statement against the SQL Server project database "
                  "and return rows.")
def run_read_only_mssql(args: Args, ctx: ToolContext) -> ToolResponse:
    if args.limit <= 0:
        raise ToolError("invalid_limit", "limit must be greater than 0.")
    limit = min(args.limit, 1000)
    query = _validate(args.query)
    engine = _engine(_database_url())
    with engine.connect() as connection:
        transaction = connection.begin()
        try:
            result = connection.execute(text(query))
            columns = list(result.keys())
            rows = [{key: _plain(value) for key, value in zip(columns, row)} for row in result.fetchmany(limit)]
        except Exception as exc:
            raise ToolError("db_query_error", f"Read-only SQL execution failed: {exc}"[:2000], retryable=True,
                            guidance="Verify table/column names and DB connectivity, then retry.") from exc
        finally:
            transaction.rollback()
    return ToolResponse({"datasource": args.datasource, "query": query, "limit": limit, "rowCount": len(rows),
                         "columns": columns, "rows": rows})

"""Read-only SQL against a consuming project database on PostgreSQL, ported from the SolidX agent's
``run_read_only_sql``. Statements are checked first, then run in a read-only transaction with a statement
timeout that is always rolled back."""

import os
import re
from functools import lru_cache

from pydantic import BaseModel, Field
from sqlalchemy import create_engine, text
from sqlalchemy.engine import make_url
from agenthub.sdk import (tool, ToolContext, ToolError, ToolResponse, ToolConfigResponse,
                          ToolInitResponse, tool_config, tool_init)

BACKEND = "postgresql"
_FORBIDDEN_SQL_RE = re.compile(
    r"\b(insert|update|delete|upsert|merge|drop|truncate|alter|create|replace|grant|revoke|vacuum|analyze|refresh)\b",
    re.IGNORECASE,
)
_ALLOWED_START_RE = re.compile(r"^\s*(select|with|explain|show)\b", re.IGNORECASE)
_SQL_COMMENT_RE = re.compile(r"(--[^\n]*|/\*.*?\*/)", re.DOTALL)


class Args(BaseModel):
    query: str = Field(description="PostgreSQL statement to execute. Only read-only statements are allowed.")
    datasource: str = Field("default", description='Datasource name (currently informational; default "default").')
    limit: int = Field(100, description="Maximum rows to return (default 100, max 1000).")


def _database_url():
    # AGENTHUB_READONLY_DATABASE_URL may point at a read-only role; DATABASE_URL is the project database.
    raw = os.environ.get("AGENTHUB_READONLY_DATABASE_URL") or os.environ.get("DATABASE_URL")
    if not raw:
        raise ToolError("db_query_error", "No project database is configured.")
    url = make_url(raw)
    if url.get_backend_name() != BACKEND:
        raise ToolError("unsupported_database", f"The project database is {url.get_backend_name()}, not PostgreSQL.",
                        guidance="Use run_read_only_mssql for SQL Server.")
    return url


@lru_cache(maxsize=2)
def _engine(url):
    return create_engine(url, pool_pre_ping=True, pool_size=2, max_overflow=0)


def _validate(sql: str) -> str:
    cleaned = _SQL_COMMENT_RE.sub("", sql or "").strip()
    if not cleaned:
        raise ToolError("invalid_query", "Query is empty.")
    if ";" in cleaned:
        raise ToolError("multiple_statements_not_allowed", "Only one read-only SQL statement is allowed.")
    if not _ALLOWED_START_RE.match(cleaned):
        raise ToolError("query_must_be_read_only", "Only read-only queries are allowed (SELECT/WITH/EXPLAIN/SHOW).",
                        retryable=True, guidance="Provide a read-only query. For DELETE/UPDATE/INSERT requests, "
                                                 "ask for SQL generation only.")
    if _FORBIDDEN_SQL_RE.search(cleaned):
        raise ToolError("forbidden_sql_operation", "Mutating SQL operations are not allowed in this tool.",
                        retryable=True, guidance="Use only read-only SQL. If you need a DELETE query, request query "
                                                 "text and run it manually after validation.")
    return cleaned


def _plain(value):
    return value if value is None or isinstance(value, (str, int, float, bool)) else str(value)


@tool_config
def config() -> ToolConfigResponse:
    # DATABASE_URL is the runtime's project database, not a Core secret.
    return ToolConfigResponse(required_secrets=[])


@tool_init
def init() -> ToolInitResponse:
    try:
        url = _database_url()
    except ToolError as exc:
        return ToolInitResponse(success=False, message=str(exc))
    engine = create_engine(url, connect_args={"connect_timeout": 5} if url.get_backend_name() == "postgresql" else {})
    try:
        with engine.connect() as connection:
            connection.execute(text("SELECT 1"))
    except Exception as exc:
        return ToolInitResponse(success=False, message=f"Could not query the project database ({type(exc).__name__}).")
    finally:
        engine.dispose()
    return ToolInitResponse(success=True, message="PostgreSQL project database connection confirmed.")


@tool(name="run_read_only_postgres",
      description="Execute a single read-only SQL statement against the PostgreSQL project database and return rows.")
def run_read_only_postgres(args: Args, ctx: ToolContext) -> ToolResponse:
    if args.limit <= 0:
        raise ToolError("invalid_limit", "limit must be greater than 0.")
    limit = min(args.limit, 1000)
    query = _validate(args.query)
    engine = _engine(_database_url())
    with engine.connect() as connection:
        transaction = connection.begin()
        try:
            if engine.dialect.name == "postgresql":
                # Defence in depth on top of the statement checks above.
                connection.execute(text("SET TRANSACTION READ ONLY"))
                connection.execute(text("SET LOCAL statement_timeout = 30000"))
            result = connection.execute(text(query))
            columns = list(result.keys())
            rows = [{key: _plain(value) for key, value in zip(columns, row)} for row in result.fetchmany(limit)]
        except Exception as exc:
            raise ToolError("db_query_error", f"Read-only SQL execution failed: {exc}"[:2000], retryable=True,
                            guidance="Verify table/column names and DB connectivity, then retry.") from exc
        finally:
            transaction.rollback()
    return ToolResponse({"datasource": args.datasource, "query": query, "limit": limit, "rowCount": len(rows),
                         "columns": columns, "rows": rows})

import re
from concurrent.futures import ThreadPoolExecutor
from html.parser import HTMLParser
from urllib.parse import parse_qs, urlparse

import requests
from pydantic import BaseModel
from agenthub.sdk import (tool, ToolContext, ToolError, ToolResponse, ToolConfigResponse,
                          ToolInitResponse, tool_config, tool_init)

SEARCH_URL = "https://html.duckduckgo.com/html/"
HEADERS = {"User-Agent": "Mozilla/5.0 (compatible; AgentHub/1.0; +https://solidxai.com)",
           "Accept-Language": "en-US,en;q=0.8"}
SKIPPED_TAGS = {"script", "style", "noscript", "svg", "nav", "footer", "header", "form", "iframe", "template"}


class Args(BaseModel):
    query: str
    max_results: int = 5
    fetch_pages: int = 0
    max_page_chars: int = 8000
    region: str = "wt-wt"


class _ResultParser(HTMLParser):
    """Collects title, url, and snippet from DuckDuckGo's HTML results page."""

    def __init__(self):
        super().__init__()
        self.results: list[dict] = []
        self.field: str | None = None

    def handle_starttag(self, tag, attrs):
        attributes = dict(attrs)
        classes = (attributes.get("class") or "").split()
        if tag == "a" and "result__a" in classes:
            self.results.append({"title": "", "url": _target(attributes.get("href") or ""), "snippet": ""})
            self.field = "title"
        elif "result__snippet" in classes and self.results:
            self.field = "snippet"

    def handle_endtag(self, tag):
        if tag in {"a", "td", "div"}:
            self.field = None

    def handle_data(self, data):
        if self.field:
            self.results[-1][self.field] += data


class _TextParser(HTMLParser):
    def __init__(self):
        super().__init__()
        self.title, self.parts, self.skipping, self.in_title = "", [], 0, False

    def handle_starttag(self, tag, attrs):
        self.skipping += tag in SKIPPED_TAGS
        self.in_title = self.in_title or tag == "title"

    def handle_endtag(self, tag):
        self.skipping -= tag in SKIPPED_TAGS and self.skipping > 0
        self.in_title = self.in_title and tag != "title"

    def handle_data(self, data):
        if self.in_title:
            self.title += data
        elif not self.skipping:
            self.parts.append(data)


def _target(href: str) -> str:
    """Unwrap DuckDuckGo's /l/?uddg= redirect."""
    parsed = urlparse(href if "://" in href else "https:" + href if href.startswith("//") else href)
    if parsed.netloc.endswith("duckduckgo.com") and parsed.path == "/l/":
        return parse_qs(parsed.query).get("uddg", [""])[0]
    return parsed.geturl()


def _clean(value: str) -> str:
    return re.sub(r"\s+", " ", value).strip()


def _fetch(url: str, max_chars: int) -> dict:
    try:
        with requests.get(url, headers=HEADERS, timeout=15, stream=True) as response:
            response.raise_for_status()
            content_type = response.headers.get("content-type", "")
            if not content_type.startswith(("text/html", "text/plain", "application/xhtml")):
                return {"error": f"Unsupported content type {content_type or 'unknown'}"}
            raw = response.raw.read(2_000_000, decode_content=True)
            html = raw.decode(response.encoding or "utf-8", errors="replace")
    except requests.RequestException as exc:
        return {"error": type(exc).__name__}
    if content_type.startswith("text/plain"):
        return {"content": _clean(html)[:max_chars]}
    parser = _TextParser()
    parser.feed(html)
    text = _clean(" ".join(parser.parts))
    return {"page_title": _clean(parser.title), "content": text[:max_chars], "truncated": len(text) > max_chars}


@tool_config
def config() -> ToolConfigResponse:
    return ToolConfigResponse(required_secrets=[])


@tool_init
def init() -> ToolInitResponse:
    try:
        response = requests.get(SEARCH_URL, headers=HEADERS, timeout=5)
    except requests.RequestException as exc:
        return ToolInitResponse(success=False, message=f"Could not reach the search provider ({type(exc).__name__}).")
    if response.status_code >= 500:
        return ToolInitResponse(success=False, message=f"Search provider returned HTTP {response.status_code}.")
    return ToolInitResponse(success=True, message="Search provider is reachable.")


@tool(name="web_search", description="Search the web and optionally fetch readable text from the top results.")
def web_search(args: Args, ctx: ToolContext) -> ToolResponse:
    if not args.query.strip():
        raise ToolError("invalid_query", "Query must not be empty")
    try:
        response = requests.post(SEARCH_URL, data={"q": args.query, "kl": args.region}, headers=HEADERS, timeout=20)
    except requests.RequestException as exc:
        raise ToolError("search_unavailable", type(exc).__name__, retryable=True) from exc
    if response.status_code != 200 or "anomaly-modal" in response.text:
        raise ToolError("search_unavailable", f"Search provider returned {response.status_code}", retryable=True,
                        guidance="Retry later or rephrase the query")
    parser = _ResultParser()
    parser.feed(response.text)
    results, seen = [], set()
    for item in parser.results:
        url = item["url"]
        if not url.startswith(("http://", "https://")) or urlparse(url).netloc.endswith("duckduckgo.com") or url in seen:
            continue
        seen.add(url)
        results.append({"title": _clean(item["title"]), "url": url, "snippet": _clean(item["snippet"])})
        if len(results) >= max(1, min(args.max_results, 10)):
            break
    fetch = results[:max(0, min(args.fetch_pages, 5))]
    if fetch:
        max_chars = max(500, min(args.max_page_chars, 20000))
        with ThreadPoolExecutor(max_workers=len(fetch)) as pool:
            for result, page in zip(fetch, pool.map(lambda item: _fetch(item["url"], max_chars), fetch)):
                result.update(page)
    return ToolResponse({"query": args.query, "results": results})
